const itens = $input.all().map((i) => i.json);

// Postgres do n8n devolve coluna `date` como timestamp completo
// ("2026-08-09T00:00:00.000Z"), não só "2026-08-09" — corta os 10
// primeiros caracteres antes de separar, funciona pros dois formatos.
function fmtData(iso) {
  const [ano, mes, dia] = String(iso).slice(0, 10).split('-');
  return `${dia}/${mes}`;
}

const partes = [`🚫 *Produtos em falta (últimos 2 dias)* — ${itens.length}`, ''];

if (itens.length === 0) {
  partes.push('Nenhum registrado.');
} else {
  itens.forEach((f) => {
    partes.push(`• ${f.nome_produto} — ${fmtData(f.data)} (${f.registrado_por})`);
  });
}

return [{ json: { mensagem: partes.join('\n').trim() } }];
